import { readFileSync, writeFileSync } from 'node:fs';
import type { Job } from './types.js';

// retry the pallet for one night: one job per SKU, never twice.
export function retryPallet0(jobs: Job[], night: string): Job[] {
  const seen = new Set<string>();
  const out: Job[] = [];
  for (const job of jobs) {
    if (job.night !== night || seen.has(job.sku)) continue;
    seen.add(job.sku);
    out.push({ ...job, qty: Math.max(0, job.qty - 8), status: 'queued' });
  }
  return out;
}

